window.TESTS[7]={"id": 7, "module": "listening", "vol": 9, "sections": [{"number": 1, "html": "<p class=\"subheading\"><b>Questions 1–10</b></p><p class=\"instruction\">Complete the form below.</p><p class=\"instruction\">Write <b>ONE WORD AND/OR A NUMBER</b> for each answer.</p><div class=\"table-scroll\"><table class=\"source-table\"><tr><td><p class=\"\"><u><i><b>Car Servicing</b></i></u></p></td></tr><tr><td><p class=\"\"><u><i><b>Example</b></i></u></p><p class=\"\">                  Customer name:            Ian Croft</p><p class=\"\"><b>Cars details</b></p><p>                  Registration number:    <span class=\"qnum\">1</span><input class=\"gap\" data-q=\"1\" aria-label=\"Câu 1\" autocomplete=\"off\" spellcheck=\"false\">      </p><p class=\"\">                  Make and model:          Vida (4-door saloon)</p><p class=\"\">                  Date of manufacture:     2001</p><p>                  Number of miles            <span class=\"qnum\">2</span><input class=\"gap\" data-q=\"2\" aria-label=\"Câu 2\" autocomplete=\"off\" spellcheck=\"false\">        </p><p class=\"\"><b>Problems</b></p><p>- needs two new  <span class=\"qnum\">3</span><input class=\"gap\" data-q=\"3\" aria-label=\"Câu 3\" autocomplete=\"off\" spellcheck=\"false\">      </p><p>- the inside <span class=\"qnum\">4</span><input class=\"gap\" data-q=\"4\" aria-label=\"Câu 4\" autocomplete=\"off\" spellcheck=\"false\">  needs fixing</p><p>- one passage seat <span class=\"qnum\">5</span><input class=\"gap\" data-q=\"5\" aria-label=\"Câu 5\" autocomplete=\"off\" spellcheck=\"false\">   is stuck</p><p>- the  <span class=\"qnum\">6</span><input class=\"gap\" data-q=\"6\" aria-label=\"Câu 6\" autocomplete=\"off\" spellcheck=\"false\">  needs replacing</p><p>- the  <span class=\"qnum\">7</span><input class=\"gap\" data-q=\"7\" aria-label=\"Câu 7\" autocomplete=\"off\" spellcheck=\"false\">  brakes of the car need attention</p><p>- needs a spare  <span class=\"qnum\">8</span><input class=\"gap\" data-q=\"8\" aria-label=\"Câu 8\" autocomplete=\"off\" spellcheck=\"false\"> key    </p><p class=\"\"><b>Service arrangements</b></p><p class=\"\">                  Date/Time:                    Tuesday 5 October 8.00 a.m.</p><p>                  Courtesy car?                Yes, preferably <span class=\"qnum\">9</span><input class=\"gap\" data-q=\"9\" aria-label=\"Câu 9\" autocomplete=\"off\" spellcheck=\"false\">     </p><p class=\"\"><b>Customer details</b></p><p class=\"\">                  Address:                        361 College Road, Norwich</p><p>                  Phone:                           <span class=\"qnum\">10</span><input class=\"gap\" data-q=\"10\" aria-label=\"Câu 10\" autocomplete=\"off\" spellcheck=\"false\">      </p></td></tr></table></div>"}, {"number": 2, "html": "<p class=\"subheading\"><b>Questions 11–15</b></p><p class=\"instruction\">Choose the correct answer.</p><div data-render-choice=\"11\"></div><div data-render-choice=\"12\"></div><div data-render-choice=\"13\"></div><div data-render-choice=\"14\"></div><div data-render-choice=\"15\"></div>\n<p class=\"subheading\"><b>Questions 16–20</b></p><p class=\"instruction\">Label the map below</p><p class=\"instruction\">Choose <b>FIVE</b> correct letters from the map, <b>A-H</b>, next to the questions <b>16-20</b>.</p><p class=\"instruction\"><b>Rosedale Library</b></p><img class=\"source-image\" src=\"Listening%20-%20Vol%209/Test%207/image1.png\" alt=\"Hình gốc trong đề [VOL 9] Listening Test 7\"><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> A</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> B</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> C</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> D</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> E</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> F</button><button class=\"token\" draggable=\"true\" data-token=\"G\"><b>G</b> G</button><button class=\"token\" draggable=\"true\" data-token=\"H\"><b>H</b> H</button></div><p class=\"matching-row\" data-drop=\"16\"><span class=\"qnum\">16</span>Children’s room <select class=\"answer-select\" data-q=\"16\" aria-label=\"Câu 16\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p><p class=\"matching-row\" data-drop=\"17\"><span class=\"qnum\">17</span>Community room <select class=\"answer-select\" data-q=\"17\" aria-label=\"Câu 17\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p><p class=\"matching-row\" data-drop=\"18\"><span class=\"qnum\">18</span>Café <select class=\"answer-select\" data-q=\"18\" aria-label=\"Câu 18\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p><p class=\"matching-row\" data-drop=\"19\"><span class=\"qnum\">19</span>Academic study room <select class=\"answer-select\" data-q=\"19\" aria-label=\"Câu 19\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p><p class=\"matching-row\" data-drop=\"20\"><span class=\"qnum\">20</span>Multimedia room <select class=\"answer-select\" data-q=\"20\" aria-label=\"Câu 20\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p>"}, {"number": 3, "html": "<p class=\"subheading\"><b>Questions 21–25</b></p><p class=\"instruction\">Choose the correct answer.</p><p class=\"\"><b>The artist Samuel Prout</b></p><div data-render-choice=\"21\"></div><div data-render-choice=\"22\"></div><div data-render-choice=\"23\"></div><div data-render-choice=\"24\"></div><div data-render-choice=\"25\"></div>\n<p class=\"subheading\"><b>Questions 26–30</b></p><p class=\"instruction\"><i>What information do the speakers give about each of the following pictures?</i></p><p class=\"instruction\">Choose <b>FIVE</b> correct answers, <b>A-G</b>, next to questions <b>26-30</b>.</p><p class=\"instruction\"><b>Information</b></p><p class=\"instruction\"><b>A one of several paintings of the same view</b></p><p class=\"instruction\"><b>B probably an inaccurate title</b></p><p class=\"instruction\"><b>C may not be genuine</b></p><p class=\"instruction\"><b>D was never finished</b></p><p class=\"instruction\"><b>E typical subject matter for Prout</b></p><p class=\"instruction\"><b>F skillful painting of light and dark</b></p><p class=\"instruction\"><b>G shows an event that never took place</b></p><p class=\"instruction\"><b>Pictures</b></p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> one of several paintings of the same view</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> probably an inaccurate title</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> may not be genuine</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> was never finished</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> typical subject matter for Prout</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> skillful painting of light and dark</button><button class=\"token\" draggable=\"true\" data-token=\"G\"><b>G</b> shows an event that never took place</button></div><p class=\"matching-row\" data-drop=\"26\"><span class=\"qnum\">26</span>A view in Germany: at Wurzburg <select class=\"answer-select\" data-q=\"26\" aria-label=\"Câu 26\"><option value=\"\">Chọn</option><option value=\"A\">A · one of several paintings of the same view</option><option value=\"B\">B · probably an inaccurate title</option><option value=\"C\">C · may not be genuine</option><option value=\"D\">D · was never finished</option><option value=\"E\">E · typical subject matter for Prout</option><option value=\"F\">F · skillful painting of light and dark</option><option value=\"G\">G · shows an event that never took place</option></select></p><p class=\"matching-row\" data-drop=\"27\"><span class=\"qnum\">27</span>Bridge on the Ouse, near York <select class=\"answer-select\" data-q=\"27\" aria-label=\"Câu 27\"><option value=\"\">Chọn</option><option value=\"A\">A · one of several paintings of the same view</option><option value=\"B\">B · probably an inaccurate title</option><option value=\"C\">C · may not be genuine</option><option value=\"D\">D · was never finished</option><option value=\"E\">E · typical subject matter for Prout</option><option value=\"F\">F · skillful painting of light and dark</option><option value=\"G\">G · shows an event that never took place</option></select></p><p class=\"matching-row\" data-drop=\"28\"><span class=\"qnum\">28</span>Wooden scene <select class=\"answer-select\" data-q=\"28\" aria-label=\"Câu 28\"><option value=\"\">Chọn</option><option value=\"A\">A · one of several paintings of the same view</option><option value=\"B\">B · probably an inaccurate title</option><option value=\"C\">C · may not be genuine</option><option value=\"D\">D · was never finished</option><option value=\"E\">E · typical subject matter for Prout</option><option value=\"F\">F · skillful painting of light and dark</option><option value=\"G\">G · shows an event that never took place</option></select></p><p class=\"matching-row\" data-drop=\"29\"><span class=\"qnum\">29</span>Venice <select class=\"answer-select\" data-q=\"29\" aria-label=\"Câu 29\"><option value=\"\">Chọn</option><option value=\"A\">A · one of several paintings of the same view</option><option value=\"B\">B · probably an inaccurate title</option><option value=\"C\">C · may not be genuine</option><option value=\"D\">D · was never finished</option><option value=\"E\">E · typical subject matter for Prout</option><option value=\"F\">F · skillful painting of light and dark</option><option value=\"G\">G · shows an event that never took place</option></select></p><p class=\"matching-row\" data-drop=\"30\"><span class=\"qnum\">30</span>Entrance to a harbor <select class=\"answer-select\" data-q=\"30\" aria-label=\"Câu 30\"><option value=\"\">Chọn</option><option value=\"A\">A · one of several paintings of the same view</option><option value=\"B\">B · probably an inaccurate title</option><option value=\"C\">C · may not be genuine</option><option value=\"D\">D · was never finished</option><option value=\"E\">E · typical subject matter for Prout</option><option value=\"F\">F · skillful painting of light and dark</option><option value=\"G\">G · shows an event that never took place</option></select></p>"}, {"number": 4, "html": "<p class=\"subheading\"><b>Questions 31–40</b></p><p class=\"instruction\">Complete the notes below</p><p class=\"instruction\">Write <b>ONE WORD ONLY</b> for each answer.</p><p class=\"\"><b>Case Study: Chocozine’s difficult decision</b></p><p class=\"\"><b>Background</b></p><p>Smith and his colleagues noticed the spread of mass-customisation in many US <span class=\"qnum\">31</span><input class=\"gap\" data-q=\"31\" aria-label=\"Câu 31\" autocomplete=\"off\" spellcheck=\"false\">      </p><p class=\"\">They decided to apply the idea to chocolate, and allow clients to decide which ingredients they wanted. </p><p class=\"\">They called their company’s ‘Chocozine’.</p><p class=\"\"><b>The email order</b></p><p>A European retailer wanted 15,000 chocolate bars to use as a <span class=\"qnum\">32</span><input class=\"gap\" data-q=\"32\" aria-label=\"Câu 32\" autocomplete=\"off\" spellcheck=\"false\"> for customers.</p><p>The deal could improve their sales and provide  <span class=\"qnum\">33</span><input class=\"gap\" data-q=\"33\" aria-label=\"Câu 33\" autocomplete=\"off\" spellcheck=\"false\">      </p><p class=\"\"><b>But there were risks:</b></p><p class=\"\">They might not have sufficient time for the job.</p><p>If they failed, it could affect their finances and their  <span class=\"qnum\">34</span><input class=\"gap\" data-q=\"34\" aria-label=\"Câu 34\" autocomplete=\"off\" spellcheck=\"false\">      </p><p>They only had three <span class=\"qnum\">35</span><input class=\"gap\" data-q=\"35\" aria-label=\"Câu 35\" autocomplete=\"off\" spellcheck=\"false\">, which was not enough.</p><p class=\"\"><b>They attempt to subcontract</b> </p><p>At first they couldn’t find a subcontract with the right  <span class=\"qnum\">36</span><input class=\"gap\" data-q=\"36\" aria-label=\"Câu 36\" autocomplete=\"off\" spellcheck=\"false\"></p><p class=\"\">A Harvard professor invited Smith to speak to students.</p><p>Many students said it would be a  <span class=\"qnum\">37</span><input class=\"gap\" data-q=\"37\" aria-label=\"Câu 37\" autocomplete=\"off\" spellcheck=\"false\">  to do the deal.</p><p>One student had a  <span class=\"qnum\">38</span><input class=\"gap\" data-q=\"38\" aria-label=\"Câu 38\" autocomplete=\"off\" spellcheck=\"false\">  in the chocolate industry.</p><p>But this subcontract had trouble with the unusual  <span class=\"qnum\">39</span><input class=\"gap\" data-q=\"39\" aria-label=\"Câu 39\" autocomplete=\"off\" spellcheck=\"false\"> of the chocolate bar.</p><p class=\"\">Chocozine finally declined the order, but their sales improved anyway.</p><p class=\"\"><b>Comment</b></p><p>Accepting <span class=\"qnum\">40</span><input class=\"gap\" data-q=\"40\" aria-label=\"Câu 40\" autocomplete=\"off\" spellcheck=\"false\"> orders has created severe problems for many new businesses. </p>"}], "passages": [], "singles": [{"n": 11, "prompt": "Why David Laws leading the meeting instead of Penny Williams today?", "options": ["Penny Williams is not well recently", "David Laws is the director now", "The meeting will be postponed"]}, {"n": 12, "prompt": "What does David say has been a problem with guest speaker talks?", "options": ["expensive tickets", "lack of publicity", "inconvenient time"]}, {"n": 13, "prompt": "What did the man say about break-in at library?", "options": ["the building was destroyed to some damage", "some valuable items were stolen", "the thieves had a good preparation"]}, {"n": 14, "prompt": "Why they want to make an extension of the library?", "options": ["it has no renovation since founded", "it need to double the number of computers", "increased number of visiting people"]}, {"n": 15, "prompt": "The investment from the city council will be deployed for", "options": ["extra staff recruitment", "buy more computers", "improve the lighting"]}, {"n": 21, "prompt": "According to Jack, why did Samuel Prout never become very famous?", "options": ["His output was very limited.", "He has seen as out-fashioned.", "His work never had a major exhibition."]}, {"n": 22, "prompt": "Dr Rubin and Jack agree that many of Prout’s problems were caused by", "options": ["poor health.", "jealous colleagues.", "an unhappy marriage."]}, {"n": 23, "prompt": "How did Prout learn painting?", "options": ["His father taught him.", "He went to art galleries.", "He copied pictures."]}, {"n": 24, "prompt": "What point does Jack make about Prout’s style?", "options": ["Prout used different styles simultaneously.", "Many other artists had a similar style.", "Prout’s style developed throughout his career."]}, {"n": 25, "prompt": "What did John Ruskin admire about Prout’s paintings?", "options": ["their realism", "their presentation of buildings", "their wide range of subject matters"]}], "pairs": [], "answers": {"1": ["BD51STR"], "2": ["180", "000", "180000"], "3": ["tyres", "tires"], "4": ["light"], "5": ["belt"], "6": ["radio"], "7": ["front"], "8": ["key"], "9": ["automatic"], "10": ["07847 355780", "07847355780"], "11": ["A"], "12": ["B"], "13": ["A"], "14": ["C"], "15": ["C"], "16": ["C"], "17": ["A"], "18": ["B"], "19": ["H"], "20": ["G"], "21": ["C"], "22": ["A"], "23": ["C"], "24": ["A"], "25": ["B"], "26": ["E"], "27": ["B"], "28": ["C"], "29": ["F"], "30": ["A"], "31": ["industries"], "32": ["gift"], "33": ["publicity"], "34": ["reputation"], "35": ["machines"], "36": ["toppings"], "37": ["mistake"], "38": ["contact"], "39": ["shape"], "40": ["big"]}, "explanations": {}, "transcriptSegments": {"1": [{"id": "s1-t1", "text": "(0:00 - 0:42)You will hear a telephone conversation between an assistant at a car service station and a customer. First, you have some time to look at questions one and two on page two. You will see that there is an example that has been done for you.\nOn this occasion only, the conversation relating to this will be played first. Good morning servicing department. Good morning, I'd like to book my car in for a service please.", "html": "<p>(0:00 - 0:42)You will hear a telephone conversation between an assistant at a car service station and a customer. First, you have some time to look at questions one and two on page two. You will see that there is an example that has been done for you.</p><p>On this occasion only, the conversation relating to this will be played first. Good morning servicing department. Good morning, I&#x27;d like to book my car in for a service please.</p>", "start": 0}, {"id": "s1-t2", "text": "(0:50 - 1:06)The customer's name is Ian Croft, so Croft has been written in the space. Now we shall begin. You should answer the questions as you listen because you will not hear the recording a second time.", "html": "<p>(0:50 - 1:06)The customer&#x27;s name is Ian Croft, so Croft has been written in the space. Now we shall begin. You should answer the questions as you listen because you will not hear the recording a second time.</p>", "start": 50}, {"id": "s1-t3", "text": "(1:07 - 1:21)Listen carefully and answer questions one and two. Good morning servicing department. Good morning, I'd like to book my car in for a service please.", "html": "<p>(1:07 - 1:21)Listen carefully and answer questions one and two. Good morning servicing department. Good morning, I&#x27;d like to book my car in for a service please.</p>", "start": 67}, {"id": "s1-t4", "text": "(1:21 - 1:25)Certainly sir. If I could just take your name. Ian Croft.", "html": "<p>(1:21 - 1:25)Certainly sir. If I could just take your name. Ian Croft.</p>", "start": 81}, {"id": "s1-t5", "text": "(1:27 - 1:48)Right, and have you had the car serviced with us before? No, I've only just moved here. Right, so I'll need to take some details of the car then. So could I have a registration number please? BD51STR. Is that B for Bravo at the beginning? Yes, that's right.", "html": "<p>(1:27 - 1:48)Right, and have you had the car serviced with us before? No, I&#x27;ve only just moved here. Right, so I&#x27;ll need to take some details of the car then. So could I have a registration number please? BD51STR. Is that B for Bravo at the beginning? Yes, that&#x27;s right.</p>", "start": 87}, {"id": "s1-t6", "text": "(1:49 - 2:06)And the make of the car? It's a Vida. Right, and is that the estate? No, the four-door saloon. Good, and do you know the date of manufacture? Mmm, about… oh hold on, I'll have to work this one out.", "html": "<p>(1:49 - 2:06)And the make of the car? It&#x27;s a Vida. Right, and is that the estate? No, the four-door saloon. Good, and do you know the date of manufacture? Mmm, about… oh hold on, I&#x27;ll have to work this one out.</p>", "start": 109}, {"id": "s1-t7", "text": "(2:06 - 2:21)We've had it for ages. It must be 2001. Right, and can you tell me what the mileage is? It's done a lot.\nLet's see, I did make a note of it. Yes, it's 180,000 miles. It's done very well actually.", "html": "<p>(2:06 - 2:21)We&#x27;ve had it for ages. It must be 2001. Right, and can you tell me what the mileage is? It&#x27;s done a lot.</p><p>Let&#x27;s see, I did make a note of it. Yes, it&#x27;s 180,000 miles. It&#x27;s done very well actually.</p>", "start": 126}, {"id": "s1-t8", "text": "(2:24 - 3:40)Before you hear the rest of the conversation, you have some time to look at questions three to ten on page two. Now listen and answer questions three to ten. Right, well now of course we'll do a full service, but are there any particular problems or things you'd like us to check? Yes, a few.\nI think a couple of the tyres probably need replacing. They're getting a bit worn. OK, we do automatically look at those, but I'll make a note of that anyway.", "html": "<p>(2:24 - 3:40)Before you hear the rest of the conversation, you have some time to look at questions three to ten on page two. Now listen and answer questions three to ten. Right, well now of course we&#x27;ll do a full service, but are there any particular problems or things you&#x27;d like us to check? Yes, a few.</p><p>I think a couple of the tyres probably need replacing. They&#x27;re getting a bit worn. OK, we do automatically look at those, but I&#x27;ll make a note of that anyway.</p>", "start": 144}, {"id": "s1-t9", "text": "(3:40 - 4:03)Then, it's not a big problem, but it's a bit annoying. When you open the car door, the light ought to come on inside automatically, but it seems to have stopped working. Right, we'll have a look at that for you.\nI'm sure we can fix that. OK, what else? Oh yes, on one of the passenger seats at the back, you can't fasten the belt. It seems to have stuck.", "html": "<p>(3:40 - 4:03)Then, it&#x27;s not a big problem, but it&#x27;s a bit annoying. When you open the car door, the light ought to come on inside automatically, but it seems to have stopped working. Right, we&#x27;ll have a look at that for you.</p><p>I&#x27;m sure we can fix that. OK, what else? Oh yes, on one of the passenger seats at the back, you can&#x27;t fasten the belt. It seems to have stuck.</p>", "start": 220}, {"id": "s1-t10", "text": "(4:03 - 4:20)It just happened yesterday, so that needs looking at. Yes, that's quite important if you carry passengers in the back. Anything else? Er, there was something.\nLet me see. Well, one thing that's actually going to need replacing, I think, is the radio. It hasn't worked for some time.", "html": "<p>(4:03 - 4:20)It just happened yesterday, so that needs looking at. Yes, that&#x27;s quite important if you carry passengers in the back. Anything else? Er, there was something.</p><p>Let me see. Well, one thing that&#x27;s actually going to need replacing, I think, is the radio. It hasn&#x27;t worked for some time.</p>", "start": 243}, {"id": "s1-t11", "text": "(4:21 - 4:35)Would you like us to give you a quote for that before we fit a new one? Yes, please. Oh, and I know what I meant to say. I know you'll check the brakes in a service, but can you have a particular look at the front ones? I think they might be a bit worn.", "html": "<p>(4:21 - 4:35)Would you like us to give you a quote for that before we fit a new one? Yes, please. Oh, and I know what I meant to say. I know you&#x27;ll check the brakes in a service, but can you have a particular look at the front ones? I think they might be a bit worn.</p>", "start": 261}, {"id": "s1-t12", "text": "(4:35 - 5:04)Certainly. I'll make a note of that too. OK.\nAnd the other thing is, I only have one key for the car and I really need a spare. Yes, we'll have to order that for you, but we can do that. Great.\nSo, when would you like to come in for the service? Well, do you have anything next week? Tuesday would be good. Er, that's the 4th of October, isn't it? No, the 5th. Yes, can you make 8am? Yes, that's fine.", "html": "<p>(4:35 - 5:04)Certainly. I&#x27;ll make a note of that too. OK.</p><p>And the other thing is, I only have one key for the car and I really need a spare. Yes, we&#x27;ll have to order that for you, but we can do that. Great.</p><p>So, when would you like to come in for the service? Well, do you have anything next week? Tuesday would be good. Er, that&#x27;s the 4th of October, isn&#x27;t it? No, the 5th. Yes, can you make 8am? Yes, that&#x27;s fine.</p>", "start": 275}, {"id": "s1-t13", "text": "(5:05 - 5:23)And the service will take a few hours, so would you like to have a courtesy car during that time? There's no extra charge. Yes, that would be good, but can I have an automatic if possible, please? We'll see what we can do. Right, and now I just need to take your address, Mr Croft.", "html": "<p>(5:05 - 5:23)And the service will take a few hours, so would you like to have a courtesy car during that time? There&#x27;s no extra charge. Yes, that would be good, but can I have an automatic if possible, please? We&#x27;ll see what we can do. Right, and now I just need to take your address, Mr Croft.</p>", "start": 305}, {"id": "s1-t14", "text": "(5:24 - 5:34)It's 361 College Road, Norwich. And would you like a phone number? Yes, please. A daytime number would be best, if possible.", "html": "<p>(5:24 - 5:34)It&#x27;s 361 College Road, Norwich. And would you like a phone number? Yes, please. A daytime number would be best, if possible.</p>", "start": 324}, {"id": "s1-t15", "text": "(5:35 - 7:09)Right, 07847 355780. Lovely. So, that's it.\nThank you very much, Mr Croft.", "html": "<p>(5:35 - 7:09)Right, 07847 355780. Lovely. So, that&#x27;s it.</p><p>Thank you very much, Mr Croft. </p>", "start": 335}], "2": [{"id": "s2-t1", "text": "Good morning, everyone. Welcome to Rosedale Library Open Day.", "html": "<p>Good morning, everyone. Welcome to Rosedale Library Open Day.</p>", "start": null}, {"id": "s2-t2", "text": "(7:10 - 7:24)It's good to see that so many members of the public are interested in the future of the library. For those of you who don't know me, my name is David Laws. I'm the new personal assistant to Penny Williams, the library director.", "html": "<p>(7:10 - 7:24)It&#x27;s good to see that so many members of the public are interested in the future of the library. For those of you who don&#x27;t know me, my name is David Laws. I&#x27;m the new personal assistant to Penny Williams, the library director.</p>", "start": 430}, {"id": "s2-t3", "text": "(7:25 - 7:41)Penny was supposed to be leading this meeting, but due to unexpected illness, I will be taking her place this morning. We felt that this would be better than postponing the meeting to a later date. Firstly, a couple of small matters.", "html": "<p>(7:25 - 7:41)Penny was supposed to be leading this meeting, but due to unexpected illness, I will be taking her place this morning. We felt that this would be better than postponing the meeting to a later date. Firstly, a couple of small matters.</p>", "start": 445}, {"id": "s2-t4", "text": "(7:42 - 8:02)The guest speaker talks this year have been incredibly popular, and the slight rise in ticket price has not put anyone off. We will continue to hold these events on a monthly basis. It has, however, come to our attention that some people have missed events because they didn't know they were on.", "html": "<p>(7:42 - 8:02)The guest speaker talks this year have been incredibly popular, and the slight rise in ticket price has not put anyone off. We will continue to hold these events on a monthly basis. It has, however, come to our attention that some people have missed events because they didn&#x27;t know they were on.</p>", "start": 462}, {"id": "s2-t5", "text": "(8:03 - 8:27)We now intend to notify everyone through email reminders. Also, you might be aware that we had a break-in last month, and while the thief or thieves actually left empty-handed, they did smash a number of windows and kick down a door trying to get in. Police believe the offenders were just taking a chance that there might be something valuable in the library.", "html": "<p>(8:03 - 8:27)We now intend to notify everyone through email reminders. Also, you might be aware that we had a break-in last month, and while the thief or thieves actually left empty-handed, they did smash a number of windows and kick down a door trying to get in. Police believe the offenders were just taking a chance that there might be something valuable in the library.</p>", "start": 483}, {"id": "s2-t6", "text": "(8:28 - 8:50)Anyway, we hope that the new security cameras along Roberts Avenue might deter this kind of activity. Now, the purpose of the meeting, of course, is to present the proposals for a new library layout. Rosedale Library has been serving the public for 50 years, but it's not been extended since the renovations in 1969.", "html": "<p>(8:28 - 8:50)Anyway, we hope that the new security cameras along Roberts Avenue might deter this kind of activity. Now, the purpose of the meeting, of course, is to present the proposals for a new library layout. Rosedale Library has been serving the public for 50 years, but it&#x27;s not been extended since the renovations in 1969.</p>", "start": 508}, {"id": "s2-t7", "text": "(8:52 - 9:14)Since opening, the number of books on our shelves and other items has more than doubled, and visitor numbers have increased 20% in the last 10 years. There is, therefore, a clear need for an extension. We hope that you have noticed some recent improvements to the library, such as the eight new PCs that were installed back in June.", "html": "<p>(8:52 - 9:14)Since opening, the number of books on our shelves and other items has more than doubled, and visitor numbers have increased 20% in the last 10 years. There is, therefore, a clear need for an extension. We hope that you have noticed some recent improvements to the library, such as the eight new PCs that were installed back in June.</p>", "start": 532}, {"id": "s2-t8", "text": "(9:15 - 9:48)We're also aware that the lighting is quite poor, but you'll shortly see a big difference because the City Council continued to support us and have authorised the spending in this area. We've also applied to the Council to approve the addition of another member of staff to work part-time in the afternoons, when mothers and children tend to use the library more often, and this decision will be made in the next few weeks. Before you hear the rest of the talk, you have some time to look at questions 16 to 20.", "html": "<p>(9:15 - 9:48)We&#x27;re also aware that the lighting is quite poor, but you&#x27;ll shortly see a big difference because the City Council continued to support us and have authorised the spending in this area. We&#x27;ve also applied to the Council to approve the addition of another member of staff to work part-time in the afternoons, when mothers and children tend to use the library more often, and this decision will be made in the next few weeks. Before you hear the rest of the talk, you have some time to look at questions 16 to 20.</p>", "start": 555}, {"id": "s2-t9", "text": "(10:08 - 10:27)Now listen and answer questions 16 to 20. Now, turning to the proposal for the extensions and alterations to the library, please see the second page of your handout. The double line indicates the rooms in the existing building, and the dotted lines show where the extensions might be.", "html": "<p>(10:08 - 10:27)Now listen and answer questions 16 to 20. Now, turning to the proposal for the extensions and alterations to the library, please see the second page of your handout. The double line indicates the rooms in the existing building, and the dotted lines show where the extensions might be.</p>", "start": 608}, {"id": "s2-t10", "text": "(10:28 - 10:56)As you can see, the location of the entrance hall to the library would remain unchanged there at the bottom of the plan. Once you go all the way through the entrance hall, on your immediate left would be the local history display that would face the information desk. Behind it, the plan is for an access ramp inside the existing building, meaning the mothers with pushchairs and wheelchair users could ascend to the first new area.", "html": "<p>(10:28 - 10:56)As you can see, the location of the entrance hall to the library would remain unchanged there at the bottom of the plan. Once you go all the way through the entrance hall, on your immediate left would be the local history display that would face the information desk. Behind it, the plan is for an access ramp inside the existing building, meaning the mothers with pushchairs and wheelchair users could ascend to the first new area.</p>", "start": 628}, {"id": "s2-t11", "text": "(10:57 - 11:19)This new room is designed to be light and airy, and could be the ideal location for a new children's room looking out onto the park. You will notice there are steps that lead back down to the ground floor. At the bottom of these, on the left, would be the adult fiction section, so no change there.", "html": "<p>(10:57 - 11:19)This new room is designed to be light and airy, and could be the ideal location for a new children&#x27;s room looking out onto the park. You will notice there are steps that lead back down to the ground floor. At the bottom of these, on the left, would be the adult fiction section, so no change there.</p>", "start": 657}, {"id": "s2-t12", "text": "(11:20 - 11:44)But behind this is proposed to construct a new community room for public lectures, special events and so forth. This will be the largest new room. To the right of the adult fiction room, with magnificent views of the sea, a cafe could provide visitors with light refreshments and an opportunity to browse a range of magazines.", "html": "<p>(11:20 - 11:44)But behind this is proposed to construct a new community room for public lectures, special events and so forth. This will be the largest new room. To the right of the adult fiction room, with magnificent views of the sea, a cafe could provide visitors with light refreshments and an opportunity to browse a range of magazines.</p>", "start": 680}, {"id": "s2-t13", "text": "(11:45 - 12:04)There would be external access to this area via a set of steps leading down towards Queen's Parade. Now, let's go back to the entrance hall again. On the right of the entrance hall, facing onto the right Roberts Avenue, is the new staff workroom.", "html": "<p>(11:45 - 12:04)There would be external access to this area via a set of steps leading down towards Queen&#x27;s Parade. Now, let&#x27;s go back to the entrance hall again. On the right of the entrance hall, facing onto the right Roberts Avenue, is the new staff workroom.</p>", "start": 705}, {"id": "s2-t14", "text": "(12:05 - 12:39)The fact that the workroom would be overlooking Roberts Avenue means the staff will actually be able to see outside rather than be stuck in the small room behind the toilets. The room looking out onto both Queen's Parade and Roberts Avenue would be the academic study room, a facility we believe could be used by the growing number of local students. Also facing Roberts Avenue but not Queen's Parade would be the multimedia room with our extensive audio collection right behind it.", "html": "<p>(12:05 - 12:39)The fact that the workroom would be overlooking Roberts Avenue means the staff will actually be able to see outside rather than be stuck in the small room behind the toilets. The room looking out onto both Queen&#x27;s Parade and Roberts Avenue would be the academic study room, a facility we believe could be used by the growing number of local students. Also facing Roberts Avenue but not Queen&#x27;s Parade would be the multimedia room with our extensive audio collection right behind it.</p>", "start": 725}, {"id": "s2-t15", "text": "(12:39 - 13:39)That is the end of Part 2. You now have half a minute to check your answers.", "html": "<p>(12:39 - 13:39)That is the end of Part 2. You now have half a minute to check your answers.</p>", "start": 759}], "3": [{"id": "s3-t1", "text": "You will hear an art history student called Jack talking to a lecturer, Dr. Reuben, about an English artist called Samuel Prout. First, you have some time to look at questions 21 to 25 on page 5. Now, listen carefully and answer questions 21 to 25.", "html": "<p>You will hear an art history student called Jack talking to a lecturer, Dr. Reuben, about an English artist called Samuel Prout. First, you have some time to look at questions 21 to 25 on page 5. Now, listen carefully and answer questions 21 to 25.</p>", "start": null}, {"id": "s3-t2", "text": "(13:42 - 13:56)Dr. Reuben? Hello, Jack. So, have you chosen which artist you're going to give your presentation on? Yes, Samuel Prout, the 19th century English watercolour painter. Right, interesting choice.", "html": "<p>(13:42 - 13:56)Dr. Reuben? Hello, Jack. So, have you chosen which artist you&#x27;re going to give your presentation on? Yes, Samuel Prout, the 19th century English watercolour painter. Right, interesting choice.</p>", "start": 822}, {"id": "s3-t3", "text": "(13:57 - 14:14)I always feel he never quite got the fame he deserved, did he? No, I think that's true. I mean, I don't think he ever went completely out of vogue even though tastes and fashions come and go. He was really prolific in his day but there's never really been a high-profile showing of his paintings.", "html": "<p>(13:57 - 14:14)I always feel he never quite got the fame he deserved, did he? No, I think that&#x27;s true. I mean, I don&#x27;t think he ever went completely out of vogue even though tastes and fashions come and go. He was really prolific in his day but there&#x27;s never really been a high-profile showing of his paintings.</p>", "start": 837}, {"id": "s3-t4", "text": "(14:15 - 14:30)That could have brought him to more people's attention. Sure, but I think it's remarkable that he achieved any critical success given the problems that he had. Apparently, he was prone to chronic chest infections throughout his life.", "html": "<p>(14:15 - 14:30)That could have brought him to more people&#x27;s attention. Sure, but I think it&#x27;s remarkable that he achieved any critical success given the problems that he had. Apparently, he was prone to chronic chest infections throughout his life.</p>", "start": 855}, {"id": "s3-t5", "text": "(14:30 - 14:44)Yes, it must have been hard for him but it seems he had a loving wife and family. And a strong network of colleagues and supporters. Yeah, I've been trying to find out what got him interested in painting in the first place.", "html": "<p>(14:30 - 14:44)Yes, it must have been hard for him but it seems he had a loving wife and family. And a strong network of colleagues and supporters. Yeah, I&#x27;ve been trying to find out what got him interested in painting in the first place.</p>", "start": 870}, {"id": "s3-t6", "text": "(14:45 - 15:02)He doesn't seem to have learned the skill from his father like so many artists of his time. No, well, I think he painstakingly reproduced other painters' works essentially sort of schooling himself. And then later on he actually became an art teacher.", "html": "<p>(14:45 - 15:02)He doesn&#x27;t seem to have learned the skill from his father like so many artists of his time. No, well, I think he painstakingly reproduced other painters&#x27; works essentially sort of schooling himself. And then later on he actually became an art teacher.</p>", "start": 885}, {"id": "s3-t7", "text": "(15:03 - 15:26)How do you feel about Prout's style of painting? It's interesting how a lot of artists you can see how their style is developing as their work matures but not so much with Prout. He seemed to have several on the go all at the same time. Yes, with others you can say oh, that must be by so-and-so and painted in around 1820, say.", "html": "<p>(15:03 - 15:26)How do you feel about Prout&#x27;s style of painting? It&#x27;s interesting how a lot of artists you can see how their style is developing as their work matures but not so much with Prout. He seemed to have several on the go all at the same time. Yes, with others you can say oh, that must be by so-and-so and painted in around 1820, say.</p>", "start": 903}, {"id": "s3-t8", "text": "(15:27 - 15:57)Right, but not so much with Prout. Of course, Prout's career had a huge boost when the art critic John Ruskin declared him a great artist. Yes, but Ruskin's assessment was quite biassed, wasn't it? How do you mean? Well, Ruskin admired Prout and he didn't seem to mind the fact that many of his paintings showed more or less the same thing European street scenes or that the people in Prout's pictures can look rather wooden and not very lifelike.", "html": "<p>(15:27 - 15:57)Right, but not so much with Prout. Of course, Prout&#x27;s career had a huge boost when the art critic John Ruskin declared him a great artist. Yes, but Ruskin&#x27;s assessment was quite biassed, wasn&#x27;t it? How do you mean? Well, Ruskin admired Prout and he didn&#x27;t seem to mind the fact that many of his paintings showed more or less the same thing European street scenes or that the people in Prout&#x27;s pictures can look rather wooden and not very lifelike.</p>", "start": 927}, {"id": "s3-t9", "text": "(15:57 - 16:50)For me, his detailing of architecture was too predictable but for Ruskin that was where Prout's genius lay. Well, I guess that's what Ruskin was particularly interested in. Before you hear the rest of the discussion you have some time to look at questions 26 to 30 on page 6. Now listen and answer questions 26 to 30.", "html": "<p>(15:57 - 16:50)For me, his detailing of architecture was too predictable but for Ruskin that was where Prout&#x27;s genius lay. Well, I guess that&#x27;s what Ruskin was particularly interested in. Before you hear the rest of the discussion you have some time to look at questions 26 to 30 on page 6. Now listen and answer questions 26 to 30.</p>", "start": 957}, {"id": "s3-t10", "text": "(16:54 - 17:25)OK, Jack, so your brief was to prepare a presentation to give to the group and show some pictures associated with the artist each of which makes a key point about their work, OK? Right, well, I wanted to start with a view in Germany at Würzburg. It's a detailed watercolour showing a busy market scene with a background of flamboyant detail like in so many of his pictures. Yes, basically what Prout had made his name doing so well.", "html": "<p>(16:54 - 17:25)OK, Jack, so your brief was to prepare a presentation to give to the group and show some pictures associated with the artist each of which makes a key point about their work, OK? Right, well, I wanted to start with a view in Germany at Würzburg. It&#x27;s a detailed watercolour showing a busy market scene with a background of flamboyant detail like in so many of his pictures. Yes, basically what Prout had made his name doing so well.</p>", "start": 1014}, {"id": "s3-t11", "text": "(17:25 - 17:37)It really gives the flavour of his work. Right. There's a painting called Bridge on the Ouse near York except that experts now think this isn't York at all but somewhere in the south of England.", "html": "<p>(17:25 - 17:37)It really gives the flavour of his work. Right. There&#x27;s a painting called Bridge on the Ouse near York except that experts now think this isn&#x27;t York at all but somewhere in the south of England.</p>", "start": 1045}, {"id": "s3-t12", "text": "(17:38 - 17:47)Right. But as far as I know the picture has never been renamed. No, that would make cataloguing and researching Prout's pictures more complicated.", "html": "<p>(17:38 - 17:47)Right. But as far as I know the picture has never been renamed. No, that would make cataloguing and researching Prout&#x27;s pictures more complicated.</p>", "start": 1058}, {"id": "s3-t13", "text": "(17:48 - 18:03)And the next one is called Woodland Scene. This one has a signature, it says S. Prout in the bottom left but even so experts on Prout say they doubt he actually painted it. Yes, I remember reading that.", "html": "<p>(17:48 - 18:03)And the next one is called Woodland Scene. This one has a signature, it says S. Prout in the bottom left but even so experts on Prout say they doubt he actually painted it. Yes, I remember reading that.</p>", "start": 1068}, {"id": "s3-t14", "text": "(18:04 - 18:19)The detailing is too clumsy with the sun not casting shade in the right place. Exactly and there's a lot of blue that basically doesn't appear in any other Prout pictures so it's probably a forgery. Yes.", "html": "<p>(18:04 - 18:19)The detailing is too clumsy with the sun not casting shade in the right place. Exactly and there&#x27;s a lot of blue that basically doesn&#x27;t appear in any other Prout pictures so it&#x27;s probably a forgery. Yes.</p>", "start": 1084}, {"id": "s3-t15", "text": "(18:19 - 18:35)And what's the next one? Venice. It's a view from the Grand Canal with some rather grand buildings. They're bathed in sunlight with a sort of picturesque shadow cast by the buildings opposite which is shown brilliantly.", "html": "<p>(18:19 - 18:35)And what&#x27;s the next one? Venice. It&#x27;s a view from the Grand Canal with some rather grand buildings. They&#x27;re bathed in sunlight with a sort of picturesque shadow cast by the buildings opposite which is shown brilliantly.</p>", "start": 1099}, {"id": "s3-t16", "text": "(18:36 - 18:41)Lovely use of colour. Prout at his best, I think. Right.", "html": "<p>(18:36 - 18:41)Lovely use of colour. Prout at his best, I think. Right.</p>", "start": 1116}, {"id": "s3-t17", "text": "(18:41 - 18:48)And then there's Entrance to a Harbour. Right. He grew up by the sea, didn't he? Yes, in Plymouth.", "html": "<p>(18:41 - 18:48)And then there&#x27;s Entrance to a Harbour. Right. He grew up by the sea, didn&#x27;t he? Yes, in Plymouth.</p>", "start": 1121}, {"id": "s3-t18", "text": "(18:49 - 19:06)He didn't specialise in seascapes but this same location with the harbour and the sea also appear in other pictures showing a range of weather conditions. They don't all have figures like this one but I think they're really well done. Right.", "html": "<p>(18:49 - 19:06)He didn&#x27;t specialise in seascapes but this same location with the harbour and the sea also appear in other pictures showing a range of weather conditions. They don&#x27;t all have figures like this one but I think they&#x27;re really well done. Right.</p>", "start": 1129}, {"id": "s3-t19", "text": "(19:06 - 19:50)That is the end of section three. You now have half a minute to check your answers.", "html": "<p>(19:06 - 19:50)That is the end of section three. You now have half a minute to check your answers. </p>", "start": 1146}], "4": [{"id": "s4-t1", "text": "Now turn to section four on page seven.", "html": "<p>Now turn to section four on page seven.</p>", "start": null}, {"id": "s4-t2", "text": "(19:53 - 20:10)You will hear part of a lecture in a business class. The professor is discussing a case study of a company in North America called Chocozine. First, you have some time to look at questions thirty-one to forty on page seven.", "html": "<p>(19:53 - 20:10)You will hear part of a lecture in a business class. The professor is discussing a case study of a company in North America called Chocozine. First, you have some time to look at questions thirty-one to forty on page seven.</p>", "start": 1193}, {"id": "s4-t3", "text": "(21:01 - 21:22)Now listen carefully and answer questions thirty-one to forty. We've been talking about small businesses and some of the challenges they face. Today, I want to look at a case study based on a company called Chocozine that illustrates the need to evaluate opportunities very carefully.", "html": "<p>(21:01 - 21:22)Now listen carefully and answer questions thirty-one to forty. We&#x27;ve been talking about small businesses and some of the challenges they face. Today, I want to look at a case study based on a company called Chocozine that illustrates the need to evaluate opportunities very carefully.</p>", "start": 1261}, {"id": "s4-t4", "text": "(21:23 - 21:48)A man called Eric Smith and two of his colleagues were struck by the mass customisation movement that was spreading through a large number of industries in the US. This involved mass-producing products and at the same time individually customising them for their customers. Why not apply the same concept to chocolate? Customers could choose the ingredients they'd like to have put into their chocolate bars.", "html": "<p>(21:23 - 21:48)A man called Eric Smith and two of his colleagues were struck by the mass customisation movement that was spreading through a large number of industries in the US. This involved mass-producing products and at the same time individually customising them for their customers. Why not apply the same concept to chocolate? Customers could choose the ingredients they&#x27;d like to have put into their chocolate bars.</p>", "start": 1283}, {"id": "s4-t5", "text": "(21:49 - 22:09)So Smith and his colleagues decided to launch a customised chocolate operation called Chocozine. Then, when Chocozine was only about nine months old, Smith received an email from a large European luxury retailer. This retailer was enquiring about ordering 15,000 bars of chocolate for their customers.", "html": "<p>(21:49 - 22:09)So Smith and his colleagues decided to launch a customised chocolate operation called Chocozine. Then, when Chocozine was only about nine months old, Smith received an email from a large European luxury retailer. This retailer was enquiring about ordering 15,000 bars of chocolate for their customers.</p>", "start": 1309}, {"id": "s4-t6", "text": "(22:09 - 22:32)They wanted to give these as a gift in their high-end stores in New York City, Miami and Los Angeles during the holiday shopping season. The offer certainly sounded enticing because Chocozine was selling fewer than 150 chocolate bars a day. Smith and his co-founders knew it could also be very good publicity, so they needed to consider it carefully.", "html": "<p>(22:09 - 22:32)They wanted to give these as a gift in their high-end stores in New York City, Miami and Los Angeles during the holiday shopping season. The offer certainly sounded enticing because Chocozine was selling fewer than 150 chocolate bars a day. Smith and his co-founders knew it could also be very good publicity, so they needed to consider it carefully.</p>", "start": 1329}, {"id": "s4-t7", "text": "(22:33 - 22:41)They had many things to consider. Obviously, it was a tempting offer. But at the same time, the risk was great.", "html": "<p>(22:33 - 22:41)They had many things to consider. Obviously, it was a tempting offer. But at the same time, the risk was great.</p>", "start": 1353}, {"id": "s4-t8", "text": "(22:42 - 23:10)They didn't know whether they could get the order completed in time. Also, if they accepted it and then it turned out they couldn't do it, what about the financial fallout as well as the possible damage to the company's reputation? As well as this, another thing they had to think about was how they were actually going to produce all these chocolate bars as the number of machines they had was limited. They only had three of them, and that clearly wasn't going to be enough.", "html": "<p>(22:42 - 23:10)They didn&#x27;t know whether they could get the order completed in time. Also, if they accepted it and then it turned out they couldn&#x27;t do it, what about the financial fallout as well as the possible damage to the company&#x27;s reputation? As well as this, another thing they had to think about was how they were actually going to produce all these chocolate bars as the number of machines they had was limited. They only had three of them, and that clearly wasn&#x27;t going to be enough.</p>", "start": 1362}, {"id": "s4-t9", "text": "(23:15 - 23:35)So they decided to think creatively and try to find a subcontractor to produce the bars. They weren't ready to pass up such a rare opportunity. Smith spent two days searching for a suitable subcontractor, but he couldn't find anyone who had experience of making bars with the type of melted toppings that Chocozine used.", "html": "<p>(23:15 - 23:35)So they decided to think creatively and try to find a subcontractor to produce the bars. They weren&#x27;t ready to pass up such a rare opportunity. Smith spent two days searching for a suitable subcontractor, but he couldn&#x27;t find anyone who had experience of making bars with the type of melted toppings that Chocozine used.</p>", "start": 1395}, {"id": "s4-t10", "text": "(23:36 - 23:47)Then something rather unexpected happened. A professor at Harvard Business School was teaching a class about product customisation. So she wrote to Smith and asked if he would speak to the students.", "html": "<p>(23:36 - 23:47)Then something rather unexpected happened. A professor at Harvard Business School was teaching a class about product customisation. So she wrote to Smith and asked if he would speak to the students.</p>", "start": 1416}, {"id": "s4-t11", "text": "(23:48 - 24:06)So in late October, Smith had an opportunity to talk about the deal to about 90 MBA students and to ask them for their advice. Many of the students thought that doing the deal with a luxury retailer would be a mistake. However, after the class, Smith spoke with one of the students.", "html": "<p>(23:48 - 24:06)So in late October, Smith had an opportunity to talk about the deal to about 90 MBA students and to ask them for their advice. Many of the students thought that doing the deal with a luxury retailer would be a mistake. However, after the class, Smith spoke with one of the students.</p>", "start": 1428}, {"id": "s4-t12", "text": "(24:07 - 24:30)This student had worked as a buyer at a major chocolate retailer, and he said he had a contact in the business who might be interested in doing the job. Smith called the new subcontractor the next day. He said he was interested in doing the order, but he found there were difficult technical issues to be worked out, including how to faithfully reproduce the distinctive shape of the Chocozine bars.", "html": "<p>(24:07 - 24:30)This student had worked as a buyer at a major chocolate retailer, and he said he had a contact in the business who might be interested in doing the job. Smith called the new subcontractor the next day. He said he was interested in doing the order, but he found there were difficult technical issues to be worked out, including how to faithfully reproduce the distinctive shape of the Chocozine bars.</p>", "start": 1447}, {"id": "s4-t13", "text": "(24:31 - 24:49)Smith thought about it, and in the end, reluctantly, he sent an email declining the luxury retailer's order. But fortunately for Chocozine, their sales picked up anyway, and the company gradually expanded its market share and is now doing very well. Chocozine's case is important.", "html": "<p>(24:31 - 24:49)Smith thought about it, and in the end, reluctantly, he sent an email declining the luxury retailer&#x27;s order. But fortunately for Chocozine, their sales picked up anyway, and the company gradually expanded its market share and is now doing very well. Chocozine&#x27;s case is important.</p>", "start": 1471}, {"id": "s4-t14", "text": "(24:50 - 25:04)They were wise to carefully consider whether they could actually manage an order of this kind. But not every small business will have the happy ending that Chocozine did. And taking on too big an order has destroyed many a small business.", "html": "<p>(24:50 - 25:04)They were wise to carefully consider whether they could actually manage an order of this kind. But not every small business will have the happy ending that Chocozine did. And taking on too big an order has destroyed many a small business.</p>", "start": 1490}, {"id": "s4-t15", "text": "(25:07 - 25:51)That is the end of section 4. You now have half a minute to check your answers. That is the end of the listening test. You now have 10 minutes to transfer your answers to the listening answer sheet.", "html": "<p>(25:07 - 25:51)That is the end of section 4. You now have half a minute to check your answers. That is the end of the listening test. You now have 10 minutes to transfer your answers to the listening answer sheet.</p>", "start": 1507}]}, "transcripts": {"1": "<p>(0:00 - 0:42)You will hear a telephone conversation between an assistant at a car service station and a customer. First, you have some time to look at questions one and two on page two. You will see that there is an example that has been done for you.</p><p>On this occasion only, the conversation relating to this will be played first. Good morning servicing department. Good morning, I&#x27;d like to book my car in for a service please.</p><p>(0:50 - 1:06)The customer&#x27;s name is Ian Croft, so Croft has been written in the space. Now we shall begin. You should answer the questions as you listen because you will not hear the recording a second time.</p><p>(1:07 - 1:21)Listen carefully and answer questions one and two. Good morning servicing department. Good morning, I&#x27;d like to book my car in for a service please.</p><p>(1:21 - 1:25)Certainly sir. If I could just take your name. Ian Croft.</p><p>(1:27 - 1:48)Right, and have you had the car serviced with us before? No, I&#x27;ve only just moved here. Right, so I&#x27;ll need to take some details of the car then. So could I have a registration number please? BD51STR. Is that B for Bravo at the beginning? Yes, that&#x27;s right.</p><p>(1:49 - 2:06)And the make of the car? It&#x27;s a Vida. Right, and is that the estate? No, the four-door saloon. Good, and do you know the date of manufacture? Mmm, about… oh hold on, I&#x27;ll have to work this one out.</p><p>(2:06 - 2:21)We&#x27;ve had it for ages. It must be 2001. Right, and can you tell me what the mileage is? It&#x27;s done a lot.</p><p>Let&#x27;s see, I did make a note of it. Yes, it&#x27;s 180,000 miles. It&#x27;s done very well actually.</p><p>(2:24 - 3:40)Before you hear the rest of the conversation, you have some time to look at questions three to ten on page two. Now listen and answer questions three to ten. Right, well now of course we&#x27;ll do a full service, but are there any particular problems or things you&#x27;d like us to check? Yes, a few.</p><p>I think a couple of the tyres probably need replacing. They&#x27;re getting a bit worn. OK, we do automatically look at those, but I&#x27;ll make a note of that anyway.</p><p>(3:40 - 4:03)Then, it&#x27;s not a big problem, but it&#x27;s a bit annoying. When you open the car door, the light ought to come on inside automatically, but it seems to have stopped working. Right, we&#x27;ll have a look at that for you.</p><p>I&#x27;m sure we can fix that. OK, what else? Oh yes, on one of the passenger seats at the back, you can&#x27;t fasten the belt. It seems to have stuck.</p><p>(4:03 - 4:20)It just happened yesterday, so that needs looking at. Yes, that&#x27;s quite important if you carry passengers in the back. Anything else? Er, there was something.</p><p>Let me see. Well, one thing that&#x27;s actually going to need replacing, I think, is the radio. It hasn&#x27;t worked for some time.</p><p>(4:21 - 4:35)Would you like us to give you a quote for that before we fit a new one? Yes, please. Oh, and I know what I meant to say. I know you&#x27;ll check the brakes in a service, but can you have a particular look at the front ones? I think they might be a bit worn.</p><p>(4:35 - 5:04)Certainly. I&#x27;ll make a note of that too. OK.</p><p>And the other thing is, I only have one key for the car and I really need a spare. Yes, we&#x27;ll have to order that for you, but we can do that. Great.</p><p>So, when would you like to come in for the service? Well, do you have anything next week? Tuesday would be good. Er, that&#x27;s the 4th of October, isn&#x27;t it? No, the 5th. Yes, can you make 8am? Yes, that&#x27;s fine.</p><p>(5:05 - 5:23)And the service will take a few hours, so would you like to have a courtesy car during that time? There&#x27;s no extra charge. Yes, that would be good, but can I have an automatic if possible, please? We&#x27;ll see what we can do. Right, and now I just need to take your address, Mr Croft.</p><p>(5:24 - 5:34)It&#x27;s 361 College Road, Norwich. And would you like a phone number? Yes, please. A daytime number would be best, if possible.</p><p>(5:35 - 7:09)Right, 07847 355780. Lovely. So, that&#x27;s it.</p><p>Thank you very much, Mr Croft. </p>", "2": "<p>Good morning, everyone. Welcome to Rosedale Library Open Day.</p><p>(7:10 - 7:24)It&#x27;s good to see that so many members of the public are interested in the future of the library. For those of you who don&#x27;t know me, my name is David Laws. I&#x27;m the new personal assistant to Penny Williams, the library director.</p><p>(7:25 - 7:41)Penny was supposed to be leading this meeting, but due to unexpected illness, I will be taking her place this morning. We felt that this would be better than postponing the meeting to a later date. Firstly, a couple of small matters.</p><p>(7:42 - 8:02)The guest speaker talks this year have been incredibly popular, and the slight rise in ticket price has not put anyone off. We will continue to hold these events on a monthly basis. It has, however, come to our attention that some people have missed events because they didn&#x27;t know they were on.</p><p>(8:03 - 8:27)We now intend to notify everyone through email reminders. Also, you might be aware that we had a break-in last month, and while the thief or thieves actually left empty-handed, they did smash a number of windows and kick down a door trying to get in. Police believe the offenders were just taking a chance that there might be something valuable in the library.</p><p>(8:28 - 8:50)Anyway, we hope that the new security cameras along Roberts Avenue might deter this kind of activity. Now, the purpose of the meeting, of course, is to present the proposals for a new library layout. Rosedale Library has been serving the public for 50 years, but it&#x27;s not been extended since the renovations in 1969.</p><p>(8:52 - 9:14)Since opening, the number of books on our shelves and other items has more than doubled, and visitor numbers have increased 20% in the last 10 years. There is, therefore, a clear need for an extension. We hope that you have noticed some recent improvements to the library, such as the eight new PCs that were installed back in June.</p><p>(9:15 - 9:48)We&#x27;re also aware that the lighting is quite poor, but you&#x27;ll shortly see a big difference because the City Council continued to support us and have authorised the spending in this area. We&#x27;ve also applied to the Council to approve the addition of another member of staff to work part-time in the afternoons, when mothers and children tend to use the library more often, and this decision will be made in the next few weeks. Before you hear the rest of the talk, you have some time to look at questions 16 to 20.</p><p>(10:08 - 10:27)Now listen and answer questions 16 to 20. Now, turning to the proposal for the extensions and alterations to the library, please see the second page of your handout. The double line indicates the rooms in the existing building, and the dotted lines show where the extensions might be.</p><p>(10:28 - 10:56)As you can see, the location of the entrance hall to the library would remain unchanged there at the bottom of the plan. Once you go all the way through the entrance hall, on your immediate left would be the local history display that would face the information desk. Behind it, the plan is for an access ramp inside the existing building, meaning the mothers with pushchairs and wheelchair users could ascend to the first new area.</p><p>(10:57 - 11:19)This new room is designed to be light and airy, and could be the ideal location for a new children&#x27;s room looking out onto the park. You will notice there are steps that lead back down to the ground floor. At the bottom of these, on the left, would be the adult fiction section, so no change there.</p><p>(11:20 - 11:44)But behind this is proposed to construct a new community room for public lectures, special events and so forth. This will be the largest new room. To the right of the adult fiction room, with magnificent views of the sea, a cafe could provide visitors with light refreshments and an opportunity to browse a range of magazines.</p><p>(11:45 - 12:04)There would be external access to this area via a set of steps leading down towards Queen&#x27;s Parade. Now, let&#x27;s go back to the entrance hall again. On the right of the entrance hall, facing onto the right Roberts Avenue, is the new staff workroom.</p><p>(12:05 - 12:39)The fact that the workroom would be overlooking Roberts Avenue means the staff will actually be able to see outside rather than be stuck in the small room behind the toilets. The room looking out onto both Queen&#x27;s Parade and Roberts Avenue would be the academic study room, a facility we believe could be used by the growing number of local students. Also facing Roberts Avenue but not Queen&#x27;s Parade would be the multimedia room with our extensive audio collection right behind it.</p><p>(12:39 - 13:39)That is the end of Part 2. You now have half a minute to check your answers.</p>", "3": "<p>You will hear an art history student called Jack talking to a lecturer, Dr. Reuben, about an English artist called Samuel Prout. First, you have some time to look at questions 21 to 25 on page 5. Now, listen carefully and answer questions 21 to 25.</p><p>(13:42 - 13:56)Dr. Reuben? Hello, Jack. So, have you chosen which artist you&#x27;re going to give your presentation on? Yes, Samuel Prout, the 19th century English watercolour painter. Right, interesting choice.</p><p>(13:57 - 14:14)I always feel he never quite got the fame he deserved, did he? No, I think that&#x27;s true. I mean, I don&#x27;t think he ever went completely out of vogue even though tastes and fashions come and go. He was really prolific in his day but there&#x27;s never really been a high-profile showing of his paintings.</p><p>(14:15 - 14:30)That could have brought him to more people&#x27;s attention. Sure, but I think it&#x27;s remarkable that he achieved any critical success given the problems that he had. Apparently, he was prone to chronic chest infections throughout his life.</p><p>(14:30 - 14:44)Yes, it must have been hard for him but it seems he had a loving wife and family. And a strong network of colleagues and supporters. Yeah, I&#x27;ve been trying to find out what got him interested in painting in the first place.</p><p>(14:45 - 15:02)He doesn&#x27;t seem to have learned the skill from his father like so many artists of his time. No, well, I think he painstakingly reproduced other painters&#x27; works essentially sort of schooling himself. And then later on he actually became an art teacher.</p><p>(15:03 - 15:26)How do you feel about Prout&#x27;s style of painting? It&#x27;s interesting how a lot of artists you can see how their style is developing as their work matures but not so much with Prout. He seemed to have several on the go all at the same time. Yes, with others you can say oh, that must be by so-and-so and painted in around 1820, say.</p><p>(15:27 - 15:57)Right, but not so much with Prout. Of course, Prout&#x27;s career had a huge boost when the art critic John Ruskin declared him a great artist. Yes, but Ruskin&#x27;s assessment was quite biassed, wasn&#x27;t it? How do you mean? Well, Ruskin admired Prout and he didn&#x27;t seem to mind the fact that many of his paintings showed more or less the same thing European street scenes or that the people in Prout&#x27;s pictures can look rather wooden and not very lifelike.</p><p>(15:57 - 16:50)For me, his detailing of architecture was too predictable but for Ruskin that was where Prout&#x27;s genius lay. Well, I guess that&#x27;s what Ruskin was particularly interested in. Before you hear the rest of the discussion you have some time to look at questions 26 to 30 on page 6. Now listen and answer questions 26 to 30.</p><p>(16:54 - 17:25)OK, Jack, so your brief was to prepare a presentation to give to the group and show some pictures associated with the artist each of which makes a key point about their work, OK? Right, well, I wanted to start with a view in Germany at Würzburg. It&#x27;s a detailed watercolour showing a busy market scene with a background of flamboyant detail like in so many of his pictures. Yes, basically what Prout had made his name doing so well.</p><p>(17:25 - 17:37)It really gives the flavour of his work. Right. There&#x27;s a painting called Bridge on the Ouse near York except that experts now think this isn&#x27;t York at all but somewhere in the south of England.</p><p>(17:38 - 17:47)Right. But as far as I know the picture has never been renamed. No, that would make cataloguing and researching Prout&#x27;s pictures more complicated.</p><p>(17:48 - 18:03)And the next one is called Woodland Scene. This one has a signature, it says S. Prout in the bottom left but even so experts on Prout say they doubt he actually painted it. Yes, I remember reading that.</p><p>(18:04 - 18:19)The detailing is too clumsy with the sun not casting shade in the right place. Exactly and there&#x27;s a lot of blue that basically doesn&#x27;t appear in any other Prout pictures so it&#x27;s probably a forgery. Yes.</p><p>(18:19 - 18:35)And what&#x27;s the next one? Venice. It&#x27;s a view from the Grand Canal with some rather grand buildings. They&#x27;re bathed in sunlight with a sort of picturesque shadow cast by the buildings opposite which is shown brilliantly.</p><p>(18:36 - 18:41)Lovely use of colour. Prout at his best, I think. Right.</p><p>(18:41 - 18:48)And then there&#x27;s Entrance to a Harbour. Right. He grew up by the sea, didn&#x27;t he? Yes, in Plymouth.</p><p>(18:49 - 19:06)He didn&#x27;t specialise in seascapes but this same location with the harbour and the sea also appear in other pictures showing a range of weather conditions. They don&#x27;t all have figures like this one but I think they&#x27;re really well done. Right.</p><p>(19:06 - 19:50)That is the end of section three. You now have half a minute to check your answers. </p>", "4": "<p>Now turn to section four on page seven.</p><p>(19:53 - 20:10)You will hear part of a lecture in a business class. The professor is discussing a case study of a company in North America called Chocozine. First, you have some time to look at questions thirty-one to forty on page seven.</p><p>(21:01 - 21:22)Now listen carefully and answer questions thirty-one to forty. We&#x27;ve been talking about small businesses and some of the challenges they face. Today, I want to look at a case study based on a company called Chocozine that illustrates the need to evaluate opportunities very carefully.</p><p>(21:23 - 21:48)A man called Eric Smith and two of his colleagues were struck by the mass customisation movement that was spreading through a large number of industries in the US. This involved mass-producing products and at the same time individually customising them for their customers. Why not apply the same concept to chocolate? Customers could choose the ingredients they&#x27;d like to have put into their chocolate bars.</p><p>(21:49 - 22:09)So Smith and his colleagues decided to launch a customised chocolate operation called Chocozine. Then, when Chocozine was only about nine months old, Smith received an email from a large European luxury retailer. This retailer was enquiring about ordering 15,000 bars of chocolate for their customers.</p><p>(22:09 - 22:32)They wanted to give these as a gift in their high-end stores in New York City, Miami and Los Angeles during the holiday shopping season. The offer certainly sounded enticing because Chocozine was selling fewer than 150 chocolate bars a day. Smith and his co-founders knew it could also be very good publicity, so they needed to consider it carefully.</p><p>(22:33 - 22:41)They had many things to consider. Obviously, it was a tempting offer. But at the same time, the risk was great.</p><p>(22:42 - 23:10)They didn&#x27;t know whether they could get the order completed in time. Also, if they accepted it and then it turned out they couldn&#x27;t do it, what about the financial fallout as well as the possible damage to the company&#x27;s reputation? As well as this, another thing they had to think about was how they were actually going to produce all these chocolate bars as the number of machines they had was limited. They only had three of them, and that clearly wasn&#x27;t going to be enough.</p><p>(23:15 - 23:35)So they decided to think creatively and try to find a subcontractor to produce the bars. They weren&#x27;t ready to pass up such a rare opportunity. Smith spent two days searching for a suitable subcontractor, but he couldn&#x27;t find anyone who had experience of making bars with the type of melted toppings that Chocozine used.</p><p>(23:36 - 23:47)Then something rather unexpected happened. A professor at Harvard Business School was teaching a class about product customisation. So she wrote to Smith and asked if he would speak to the students.</p><p>(23:48 - 24:06)So in late October, Smith had an opportunity to talk about the deal to about 90 MBA students and to ask them for their advice. Many of the students thought that doing the deal with a luxury retailer would be a mistake. However, after the class, Smith spoke with one of the students.</p><p>(24:07 - 24:30)This student had worked as a buyer at a major chocolate retailer, and he said he had a contact in the business who might be interested in doing the job. Smith called the new subcontractor the next day. He said he was interested in doing the order, but he found there were difficult technical issues to be worked out, including how to faithfully reproduce the distinctive shape of the Chocozine bars.</p><p>(24:31 - 24:49)Smith thought about it, and in the end, reluctantly, he sent an email declining the luxury retailer&#x27;s order. But fortunately for Chocozine, their sales picked up anyway, and the company gradually expanded its market share and is now doing very well. Chocozine&#x27;s case is important.</p><p>(24:50 - 25:04)They were wise to carefully consider whether they could actually manage an order of this kind. But not every small business will have the happy ending that Chocozine did. And taking on too big an order has destroyed many a small business.</p><p>(25:07 - 25:51)That is the end of section 4. You now have half a minute to check your answers. That is the end of the listening test. You now have 10 minutes to transfer your answers to the listening answer sheet.</p>"}, "questionSegments": {"1": ["s1-t5"], "2": ["s1-t7"], "3": ["s1-t8"], "4": ["s1-t9"], "5": ["s1-t9"], "6": ["s1-t10"], "7": ["s1-t11"], "8": ["s1-t12"], "9": ["s1-t13"], "10": ["s1-t15"], "11": ["s2-t3"], "12": ["s2-t4"], "13": ["s2-t5"], "14": ["s2-t7"], "15": ["s2-t8"], "16": ["s2-t11"], "17": ["s2-t12"], "18": ["s2-t12"], "19": ["s2-t14"], "20": ["s2-t14"], "21": ["s3-t3"], "22": ["s3-t4"], "23": ["s3-t6"], "24": ["s3-t7"], "25": ["s3-t9"], "26": ["s3-t10"], "27": ["s3-t11"], "28": ["s3-t14"], "29": ["s3-t15"], "30": ["s3-t18"], "31": ["s4-t4"], "32": ["s4-t6"], "33": ["s4-t6"], "34": ["s4-t8"], "35": ["s4-t8"], "36": ["s4-t9"], "37": ["s4-t11"], "38": ["s4-t12"], "39": ["s4-t12"], "40": ["s4-t14"]}, "headingsBySection": {}, "grading": {"pairs": [], "sets": []}, "groups": [[1, 10], [11, 20], [21, 30], [31, 40]], "questionTypes": {"1": "gap", "2": "gap", "3": "gap", "4": "gap", "5": "gap", "6": "gap", "7": "gap", "8": "gap", "9": "gap", "10": "gap", "11": "single", "12": "single", "13": "single", "14": "single", "15": "single", "16": "matching", "17": "matching", "18": "matching", "19": "matching", "20": "matching", "21": "single", "22": "single", "23": "single", "24": "single", "25": "single", "26": "matching", "27": "matching", "28": "matching", "29": "matching", "30": "matching", "31": "gap", "32": "gap", "33": "gap", "34": "gap", "35": "gap", "36": "gap", "37": "gap", "38": "gap", "39": "gap", "40": "gap"}, "sourceAnswerKey": {"1": ["BD51STR"], "2": ["180", "000", "180000"], "3": ["tyres", "tires"], "4": ["light"], "5": ["belt"], "6": ["radio"], "7": ["front"], "8": ["key"], "9": ["automatic"], "10": ["07847 355780", "07847355780"], "11": ["A"], "12": ["B"], "13": ["A"], "14": ["C"], "15": ["C"], "16": ["C"], "17": ["A"], "18": ["B"], "19": ["H"], "20": ["G"], "21": ["C"], "22": ["A"], "23": ["C"], "24": ["A"], "25": ["B"], "26": ["E"], "27": ["B"], "28": ["C"], "29": ["F"], "30": ["A"], "31": ["industries"], "32": ["publicity"], "33": ["machines"], "34": ["mistake"], "35": ["shape"], "36": ["gift"], "37": ["reputation"], "38": ["toppings"], "39": ["contact"], "40": ["big"]}, "sourceNotes": ["Key nguồn câu 32–39 bị lệch thứ tự. Đáp án trên web được đối chiếu lại từng chỗ trống với transcript gốc; bản key ban đầu được giữ trong dữ liệu nguồn để đối chiếu."], "hasAnswerKey": true};
